function preAnusvaraVowelSubstitution(state, config) {
  const NGA = '\u0999'; // ঙ
  let input = state.input.replace(/[\u200c\u200d]/g, '');
  const matras = config.maps.forward.matras || [];

  const getMatra = (key) => {
    const match = matras.find(p => p[0] === key);
    return match ? match[1] : '';
  };

  // ONLY handle standard 'ng' here. Do not intercept 'ngg'!
  const subs = [
    ['ngai',  NGA + getMatra('a') + (config.maps.forward.independent_vowels.find(p => p[0] === 'i')[1] || 'ই')],
    ['ngOI',  NGA + getMatra('OI')],
    ['ngOU',  NGA + getMatra('OU')],
    ['ngaa',  NGA + (getMatra('aa')  || getMatra('A'))],
    ['ngee',  NGA + (getMatra('ee')  || getMatra('ii'))],
    ['ngii',  NGA + getMatra('ii')],
    ['nguu',  NGA + (getMatra('uu')  || getMatra('U'))],
    ['ngA',   NGA + getMatra('A')],
    ['ngU',   NGA + getMatra('U')],
    ['ngrri', NGA + getMatra('rri')],
    ['ngai',  NGA + getMatra('ai')],
    ['ngO',   NGA + getMatra('O')],
    ['nge',   NGA + getMatra('e')],
    ['ngi',   NGA + getMatra('i')],
    ['nga',   NGA + getMatra('a')],
    ['ngo',   NGA],
  ];

  for (const [from, to] of subs) {
    if (to !== undefined && to !== null && input.includes(from)) {
      input = input.split(from).join(to);
      state.log.push('[PRE ANUSVARA] ' + from + ' → ' + to);
    }
  }

  state.input = input;
  return state;
}

function fwdLoopRHandling(state, config) {
    if (state.handled) return state;

    const input = state.input;
    const pos   = state.pos;

    const fwdMap       = config.maps.forward;
    const consArr      = Array.isArray(fwdMap.consonants)
                           ? fwdMap.consonants
                           : Object.entries(fwdMap.consonants || {});
    const consonantMap = Object.fromEntries(consArr.filter(p => p[0] !== '_meta'));
    const sortedCons   = Object.keys(consonantMap).sort((a, b) => b.length - a.length);
    const matraArr     = Array.isArray(fwdMap.matras)
                           ? fwdMap.matras
                           : Object.entries(fwdMap.matras || {});
    const sortedMatras = matraArr
                           .filter(p => p[0] !== '_meta')
                           .map(p => p[0])
                           .sort((a, b) => b.length - a.length);

    // ── Case 1: \uE000 ('rr') + consonant → ৰ্ (halanta, no ZWJ) ─────────────
    if (input.startsWith('\uE000', pos)) {
        const nextPos    = pos + 1;
        const matraMatch = sortedMatras.find(mk => input.startsWith(mk, nextPos));
        if (matraMatch !== undefined) return state;

        const nextCons = sortedCons.find(ck => input.startsWith(ck, nextPos));
        if (!nextCons) return state;

        state.output             += consonantMap['r'] + config.virama;
        state.pos                 = nextPos;
        state.prev.was_consonant  = true;
        state.handled             = true;
        state.log.push('[RR-HALANTA] rr before ' + nextCons + ' → ৰ্');
        return state;
    }

    // ── Case 2: \uE001 ('r') + consonant → bare ৰ (no halanta) ──────────────
    if (input.startsWith('\uE001', pos)) {
        const nextPos    = pos + 1;
        const matraMatch = sortedMatras.find(mk => input.startsWith(mk, nextPos));
        if (matraMatch !== undefined) {
            // r + matra (e.g. 'ra', 'ri') → emit bare ৰ, let Step 3 handle matra
            state.output             += consonantMap['r'];
            state.pos                 = nextPos;
            state.prev.was_consonant  = true;
            state.handled             = true;
            state.log.push('[R+MATRA] r before matra → ৰ, matra follows');
            return state;
        }

        const nextCons = sortedCons.find(ck => input.startsWith(ck, nextPos));
        if (nextCons) {
            // r + consonant → bare ৰ (no halanta)
            state.output             += consonantMap['r'];
            state.pos                 = nextPos;
            state.prev.was_consonant  = true;
            state.handled             = true;
            state.log.push('[R-BARE] r before ' + nextCons + ' → ৰ (no halanta)');
            return state;
        }

        // r at end of word or before non-alpha → emit bare ৰ
        state.output             += consonantMap['r'];
        state.pos                 = nextPos;
        state.prev.was_consonant  = true;
        state.handled             = true;
        state.log.push('[R-END] r → ৰ');
        return state;
    }

    return state;
}

function preRephMarker(state, config) {
    const fwdMap   = config.maps.forward;
    const consArr  = Array.isArray(fwdMap.consonants)
                       ? fwdMap.consonants
                       : Object.entries(fwdMap.consonants || {});
    const sortedCons = consArr
                         .filter(p => p[0] !== '_meta')
                         .map(p => p[0])
                         .sort((a, b) => b.length - a.length);

    const matraArr   = Array.isArray(fwdMap.matras)
                         ? fwdMap.matras
                         : Object.entries(fwdMap.matras || {});
    const sortedMatras = matraArr
                           .filter(p => p[0] !== '_meta')
                           .map(p => p[0])
                           .sort((a, b) => b.length - a.length);

    let input  = state.input;
    let result = '';
    let i      = 0;

    while (i < input.length) {
        // Try 'rr' first — but NOT if it is the start of 'rri' matra
        if (input.startsWith('rr', i)) {
            const after          = i + 2;
            const isRRI          = input.startsWith('rri', i);
            const nextIsConsonant = sortedCons.some(ck => input.startsWith(ck, after));
            if (!isRRI && nextIsConsonant) {
                result += '\uE000';
                i      += 2;
                continue;
            }
        }
        // Try single 'r' — but NOT if it is the start of 'rri' matra
        if (input.startsWith('r', i)) {
            const isRRI          = input.startsWith('rri', i);  // ← guard added
            const after          = i + 1;
            const nextIsConsonant = sortedCons.some(ck => input.startsWith(ck, after));
            const nextIsMatra     = sortedMatras.some(mk => input.startsWith(mk, after));
            if (!isRRI && (nextIsConsonant || (!nextIsMatra && !/[a-zA-Z]/.test(input[after] || '')))) {
                result += '\uE001';
                i      += 1;
                continue;
            }
        }
        result += input[i];
        i++;
    }

    state.input = result;
    return state;
}

function fwdLoopVowelAfterVowel(state, config) {
  const matraKeys = (config.maps.forward.matras || [])
    .filter(function(p) { return Array.isArray(p) && p[0] !== '_meta' && p[0] !== 'o'; })
    .map(function(p) { return p[0]; })
    .sort(function(a, b) { return b.length - a.length; });

  const consumed     = state.input.slice(0, state.pos);
  const prevWasMatra = state.prev.was_matra
    || matraKeys.some(function(mk) { return consumed.endsWith(mk); })
    || consumed.endsWith('o');

  if (!prevWasMatra) return state;

  const ivMap = {};
  (config.maps.forward.independent_vowels || []).forEach(function(p) {
    if (Array.isArray(p) && p[0] !== '_meta') ivMap[p[0]] = p[1];
  });
  const sortedIV = Object.keys(ivMap).sort(function(a, b) { return b.length - a.length; });

  const ivMatch = sortedIV.find(function(vk) {
    return state.input.startsWith(vk, state.pos);
  });
  if (!ivMatch) return state;

  state.output  += ivMap[ivMatch];
  state.pos     += ivMatch.length;
  state.prev     = { token: ivMatch, was_consonant: false, was_matra: false };
  state.handled  = true;
  state.log.push('[V+V INDEP] ' + ivMatch + ' → ' + ivMap[ivMatch] + ' (independent vowel after matra)');
  return state;
}

function preRConsonantVowelSeparation(state, config) {
  const zwnj = config.zwnj || "\u200C";

  const consonants = (config.maps.forward.consonants || [])
    .filter(p => Array.isArray(p))
    .map(p => p[0])
    .sort((a, b) => b.length - a.length);

  const vowels = (config.maps.forward.matras || [])
    .filter(p => Array.isArray(p) && p[0] !== "o") // exclude inherent vowel
    .map(p => p[0])
    .sort((a, b) => b.length - a.length);

  let input = state.input;

  for (const c of consonants) {
    for (const v of vowels) {
      const from = "r" + c + v;
      const to   = "r" + zwnj + c + v;

      // FIX: Ensure 'r' is not preceded by 'r', AND 'c' is not another 'r'.
      // This completely preserves 'rr' clusters from being broken by layout insertion.
      if (c !== 'r') {
        const targetRegex = new RegExp("(?<!r)" + from, "g");

        if (targetRegex.test(input)) {
          input = input.replace(targetRegex, to);
          state.log.push("[PRE R+C+V SAFE] Ignored rr clusters for: " + from);
        }
      }
    }
  }

  state.input = input;
  return state;
}

function preRephImmediateConsonant(state, config) {
  // 1. Get all consonants from configuration maps
  const consonants = (config.maps.forward.consonants || [])
    .filter(p => Array.isArray(p) && p[0] !== "_meta")
    .map(p => p[0])
    .sort((a, b) => b.length - a.length);

  let input = state.input;

  for (const c of consonants) {
    // DYNAMIC EXCLUSION: If the consonant is 'y' (for y-phala layout compatibility),
    // or if 'rr' forms a legitimate phonetic cluster root, skip splitting it.
    if (c === 'y') continue;

    // This regex looks for 'rr' followed by your consonant 'c'
    const pattern = new RegExp("rr" + c.replace(/[.*+?^${}()|[\\]\\]/g, "\\\\$&"), "g");

    // CRITICAL FIX: Only split if the 'rr' is part of an isolated layout break, 
    // otherwise let it pass to the core engine to render as a natural Reph (e.g., rrg -> ৰ্গ)
    if (input.match(pattern)) {
      // By removing the forced 'r,' conversion here for standard layout roots,
      // we allow 'durrga' to drop into the core engine naturally.
      state.log.push("[PRE REPH] Allowed natural cluster handling for: rr" + c);
    }
  }

  state.input = input;
  return state;
}
